// ---- 9. convert_to_pint_unit / UREG ----------------------------------------------------------

interface PintOutcome {
  k: 'unit' | 'str' | 'raise';
  v: string;
  /** `repr()` of a unit outcome (insertion order, unlike `str()`). */
  r?: string;
  m?: string;
}
interface PintCase {
  u: string;
  conv: PintOutcome;
  imp: PintOutcome;
  /** `str(UREG(u).units)` / `repr(...)`, or the exception. */
  units: PintOutcome;
  has: boolean | string;
}

function tsOutcome(fn: () => string | Unit): PintOutcome {
  try {
    const r = fn();
    // pint's str()/repr() can raise too (e.g. a complex exponent has no "n" format): keep that inside the try.
    return r instanceof Unit ? { k: 'unit', v: r.toString(), r: r.repr() } : { k: 'str', v: r };
  } catch (e) {
    const err = e as Error;
    // TS-side Python exceptions carry the Python class name in `name`.
    return { k: 'raise', v: err.name, m: err.message.slice(0, 80) };
  }
}

function tsConvert(u: string, system?: string): PintOutcome {
  return tsOutcome(() => (system === undefined ? convert_to_pint_unit(u) : convert_to_pint_unit(u, { volumetric_units_system: system })));
}

function tsHas(u: string): boolean | string {
  try {
    return UREG.has(u);
  } catch (e) {
    return `raise:${(e as Error).name}`;
  }
}

/** Comparison key: the exception CLASS is part of the contract (the port must raise what pint raises). */
function pintKey(o: PintOutcome): string {
  if (o.k === 'raise') return `raise:${o.v}`;
  return `${o.k}:${JSON.stringify(o.v)}${o.r !== undefined ? '|' + JSON.stringify(o.r) : ''}`;
}

function pintShow(o: PintOutcome): string {
  return o.k === 'raise' ? `raise (${o.v}: ${o.m ?? ''})` : pintKey(o);
}

describeEval('convert_to_pint_unit / UREG ↔ pint', () => {
  const cases = load<PintCase[]>('pint');

  it('convert_to_pint_unit(u) (us_customary)', () => {
    const d = new Diff('convert_to_pint_unit');
    for (const c of cases) {
      const ts = tsConvert(c.u);
      if (c.conv.k === 'raise' && ts.k === 'raise') d.note(`both raise: py ${c.conv.v} / ts ${ts.v}`);
      d.check(show(c.u), pintKey(c.conv), pintKey(ts), pintShow(c.conv), pintShow(ts));
    }
    d.finish();
  });

  it('convert_to_pint_unit(u, "imperial")', () => {
    const d = new Diff('convert_to_pint_unit[imperial]');
    for (const c of cases) {
      const ts = tsConvert(c.u, 'imperial');
      if (c.imp.k === 'raise' && ts.k === 'raise') d.note(`both raise: py ${c.imp.v} / ts ${ts.v}`);
      d.check(show(c.u), pintKey(c.imp), pintKey(ts), pintShow(c.imp), pintShow(ts));
    }
    d.finish();
  });

  it('UREG(u).units ↔ str()/repr() or the exception', () => {
    const d = new Diff('UREG(u).units');
    for (const c of cases) {
      const ts = tsOutcome(() => UREG(c.u).units);
      d.check(show(c.u), pintKey(c.units), pintKey(ts), pintShow(c.units), pintShow(ts));
    }
    d.finish();
  });

  it('UREG.has(u) ↔ u in UREG', () => {
    const d = new Diff('UREG.has');
    let trues = 0;
    for (const c of cases) {
      const ts = tsHas(c.u);
      if (c.has === true) trues += 1;
      d.check(show(c.u), String(c.has), String(ts));
    }
    d.note(`python says True for ${trues}/${cases.length} inputs`);
    d.finish();
  });
});

// ---- 9b. the pint front end: tokenize.tokenize and string_preprocessor ------------------------

interface PyTokenizeCase {
  s: string;
  toks?: [string, string][];
  raise?: string;
  m?: string;
}

describeEval('tokenizer ↔ CPython tokenize.tokenize (extra_tokens)', () => {
  const cases = load<PyTokenizeCase[]>('pytokenize');
  it('token types, strings and exception classes', () => {
    const d = new Diff('tokenize.tokenize');
    for (const c of cases) {
      const py = c.toks !== undefined ? JSON.stringify(c.toks) : `raise:${c.raise}`;
      let ts: string;
      let tsShow: string;
      try {
        const toks: TokenInfo[] = tokenizer(c.s);
        ts = JSON.stringify(toks.map((t) => [t.type, t.string]));
        tsShow = ts;
      } catch (e) {
        const err = e as Error;
        ts = `raise:${err.name}`;
        tsShow = `raise:${err.name} (${err.message.slice(0, 80)})`;
      }
      d.check(show(c.s), py, ts, c.raise !== undefined ? `raise:${c.raise} (${c.m ?? ''})` : py, tsShow);
    }
    d.finish();
  });
});

describeEval('string_preprocessor ↔ pint.util.string_preprocessor', () => {
  const cases = load<[string, string][]>('pypreprocess');
  it('registry preprocessors + string_preprocessor', () => {
    const d = new Diff('string_preprocessor');
    for (const [s, py] of cases) d.check(show(s), show(py), show(string_preprocessor(registry_preprocess(s))));
    d.finish();
  });
});

